-- Run in Supabase SQL Editor. Change the starter code before sharing the site.
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table if not exists private.group_access (id boolean primary key default true check (id), code_hash text not null);
alter table private.group_access enable row level security;
revoke all on private.group_access from public, anon, authenticated;

create table if not exists public.songs (id text primary key, title text not null, category text not null, key text, artist text, singers text, streaming_url text);
create table if not exists public.practice_sessions (id uuid primary key default gen_random_uuid(), song_id text not null references public.songs(id), song_title text not null, started_at timestamptz not null default now(), ended_at timestamptz, started_by text);
create table if not exists public.practice_notes (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.practice_sessions(id) on delete cascade, contributor text not null, section text not null, note text not null, created_at timestamptz not null default now());
create table if not exists public.current_practice_slot (slot boolean primary key default true check(slot), session_id uuid references public.practice_sessions(id));
create or replace view public.current_practice with (security_invoker=true) as select true as slot, p.* from public.current_practice_slot c left join public.practice_sessions p on p.id=c.session_id where c.slot=true and c.session_id is not null;

alter table public.songs enable row level security;
alter table public.practice_sessions enable row level security;
alter table public.practice_notes enable row level security;
alter table public.current_practice_slot enable row level security;
drop policy if exists public_read_songs on public.songs; create policy public_read_songs on public.songs for select to anon, authenticated using (true);
drop policy if exists public_read_sessions on public.practice_sessions; create policy public_read_sessions on public.practice_sessions for select to anon, authenticated using (true);
drop policy if exists public_read_notes on public.practice_notes; create policy public_read_notes on public.practice_notes for select to anon, authenticated using (true);
drop policy if exists public_read_current on public.current_practice_slot; create policy public_read_current on public.current_practice_slot for select to anon, authenticated using (true);
grant select on public.songs,public.practice_sessions,public.practice_notes,public.current_practice_slot,public.current_practice to anon,authenticated;
revoke insert,update,delete on public.songs,public.practice_sessions,public.practice_notes,public.current_practice_slot from anon,authenticated;

create or replace function public.start_practice(p_code text,p_song_id text) returns public.practice_sessions language plpgsql security definer set search_path=public,private,extensions as $$
declare s public.songs; p public.practice_sessions; stored_hash text;
begin select code_hash into stored_hash from private.group_access where id=true; if stored_hash is null or crypt(p_code,stored_hash)<>stored_hash then raise exception 'invalid access code'; end if; select * into s from public.songs where id=p_song_id; if not found then raise exception 'song not found'; end if; insert into public.practice_sessions(song_id,song_title) values(s.id,s.title) returning * into p; update public.current_practice_slot set session_id=p.id where slot=true; return p; end; $$;
create or replace function public.finish_practice(p_code text,p_session_id uuid) returns void language plpgsql security definer set search_path=public,private,extensions as $$
declare stored_hash text; begin select code_hash into stored_hash from private.group_access where id=true; if stored_hash is null or crypt(p_code,stored_hash)<>stored_hash then raise exception 'invalid access code'; end if; update public.practice_sessions set ended_at=now() where id=p_session_id and ended_at is null; update public.current_practice_slot set session_id=null where slot=true and session_id=p_session_id; end; $$;
create or replace function public.add_practice_note(p_code text,p_session_id uuid,p_contributor text,p_section text,p_note text) returns public.practice_notes language plpgsql security definer set search_path=public,private,extensions as $$
declare stored_hash text; n public.practice_notes; begin select code_hash into stored_hash from private.group_access where id=true; if stored_hash is null or crypt(p_code,stored_hash)<>stored_hash then raise exception 'invalid access code'; end if; if length(trim(p_contributor)) not between 1 and 50 or length(trim(p_section)) not between 1 and 40 or length(trim(p_note)) not between 1 and 1500 then raise exception 'invalid note fields'; end if; insert into public.practice_notes(session_id,contributor,section,note) select p_session_id,trim(p_contributor),trim(p_section),trim(p_note) where exists(select 1 from public.practice_sessions where id=p_session_id); if not found then raise exception 'session not found'; end if; select * into n from public.practice_notes where id=currval(pg_get_serial_sequence('public.practice_notes','id')); return n; exception when undefined_function or invalid_parameter_value then select * into n from public.practice_notes where session_id=p_session_id and contributor=trim(p_contributor) and section=trim(p_section) and note=trim(p_note) order by created_at desc limit 1; return n; end; $$;
create or replace function public.add_practice_note(p_code text,p_session_id uuid,p_contributor text,p_section text,p_note text) returns public.practice_notes language plpgsql security definer set search_path=public,private,extensions as $$
declare stored_hash text; n public.practice_notes; begin select code_hash into stored_hash from private.group_access where id=true; if stored_hash is null or crypt(p_code,stored_hash)<>stored_hash then raise exception 'invalid access code'; end if; if length(trim(p_contributor)) not between 1 and 50 or length(trim(p_section)) not between 1 and 40 or length(trim(p_note)) not between 1 and 1500 then raise exception 'invalid note fields'; end if; insert into public.practice_notes(session_id,contributor,section,note) select p_session_id,trim(p_contributor),trim(p_section),trim(p_note) where exists(select 1 from public.practice_sessions where id=p_session_id) returning * into n; if n.id is null then raise exception 'session not found'; end if; return n; end; $$;
revoke all on function public.start_practice(text,text),public.finish_practice(text,uuid),public.add_practice_note(text,uuid,text,text,text) from public;
grant execute on function public.start_practice(text,text),public.finish_practice(text,uuid),public.add_practice_note(text,uuid,text,text,text) to anon,authenticated;

-- Seed repertoire. Edit song metadata and add universal streaming links here or in the app later.

alter publication supabase_realtime add table public.practice_sessions;
alter publication supabase_realtime add table public.practice_notes;
alter publication supabase_realtime add table public.songs;

-- Code-checked RPC to clear all history (the notes are deleted by the session FK cascade).
create or replace function public.clear_practice_history(p_code text) returns integer language plpgsql security definer set search_path=public,private,extensions as $$
declare stored_hash text; deleted_count integer;
begin
  select code_hash into stored_hash from private.group_access where id=true;
  if stored_hash is null or crypt(p_code,stored_hash)<>stored_hash then raise exception 'invalid access code'; end if;
  update public.current_practice_slot set session_id=null where slot=true;
  delete from public.practice_sessions where true;
  get diagnostics deleted_count = row_count;
  return deleted_count;
end; $$;
revoke all on function public.clear_practice_history(text) from public;
grant execute on function public.clear_practice_history(text) to anon,authenticated;
